import{_ as o,C as i,o as r,c as h,j as e,a,b as l,w as s,E as c,a3 as d,a4 as m}from"./chunks/framework.DyX1TuK3.js";const k=JSON.parse('{"title":"Honest match","description":"","frontmatter":{},"headers":[],"relativePath":"en/honest.md","filePath":"en/honest.md"}'),u={name:"en/honest.md"};function g(b,t,f,p,y,w){const n=i("Mermaid");return r(),h("div",null,[t[1]||(t[1]=e("h1",{id:"honest-match",tabindex:"-1"},[a("Honest match "),e("a",{class:"header-anchor",href:"#honest-match","aria-label":'Permalink to "Honest match"'},"​")],-1)),t[2]||(t[2]=e("p",null,[a("The most dangerous thing a search engine can do isn't failing to find — it's "),e("strong",null,"pretending it found something when it didn't"),a(". This prototype blocks fake perfection at the last gate: it splits every search into "),e("strong",null,"three confidence tiers"),a(` by "does the library actually have this," so the top result's % honestly reflects the match instead of always reading 100%.`)],-1)),(r(),l(d,null,{default:s(()=>[c(n,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20Q%5B%22raw-sentence%20vector%20%C3%97%20library%20best%20cosine%22%5D%20--%3E%20G%7B%22which%20tier%3F%22%7D%0A%20%20%20%20G%20--%3E%7C%22%E2%89%A5%200.52%22%7C%20H%5B%22%E2%9C%85%20strong%20match%3Cbr%2F%3Ecaps%20at%2095%25%22%5D%0A%20%20%20%20G%20--%3E%7C%220.45%20%E2%80%93%200.52%22%7C%20M%5B%22%E2%97%90%20partial%20match%3Cbr%2F%3Ecaps%20at%2068%25%22%5D%0A%20%20%20%20G%20--%3E%7C%22%3C%200.45%22%7C%20L%5B%22%E2%9A%A0%20no%20strong%20match%20%C2%B7%20semantic%20guess%3Cbr%2F%3Ecaps%20at%2042%25%20%2B%20warning%22%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=m('<h2 id="the-problem-relative-scores-lie-by-nature" tabindex="-1">The problem: relative scores lie by nature <a class="header-anchor" href="#the-problem-relative-scores-lie-by-nature" aria-label="Permalink to &quot;The problem: relative scores lie by nature&quot;">​</a></h2><p>Internal ranking scores are <strong>relative</strong> (RRF fusion + cross-encoder blends are min-max normalized), so the top of any batch always maps to 1.0. Even when nothing is relevant, #1 still shows <strong>100%</strong> — a perfect score with no way to understand why.</p><h2 id="why-the-reranker-s-score-can-t-be-the-quality" tabindex="-1">Why the reranker&#39;s score can&#39;t be the quality <a class="header-anchor" href="#why-the-reranker-s-score-can-t-be-the-quality" aria-label="Permalink to &quot;Why the reranker&#39;s score can&#39;t be the quality&quot;">​</a></h2><p>Tempting: &quot;the cross-encoder scores each pair, just use that as the %.&quot; <strong>Measurement says no</strong> — searching &quot;Michael Jackson&quot; (zero relevant films in the library), the CE still gives #1 a <strong>0.88</strong>. The CE rates out-of-domain films just as highly, so it <strong>can&#39;t be an absolute quality signal</strong>. We use it only for <em>ordering</em>, not the %.</p><h2 id="the-signal-that-is-trustworthy-cosine" tabindex="-1">The signal that is trustworthy: cosine <a class="header-anchor" href="#the-signal-that-is-trustworthy-cosine" aria-label="Permalink to &quot;The signal that is trustworthy: cosine&quot;">​</a></h2><p>Use the user&#39;s <strong>raw-sentence</strong> vector against the library for the best cosine (not the AI-imagined plot vector — that&#39;s written to match the answer and runs high). It&#39;s a clean yardstick for &quot;is there a real match&quot;:</p><table tabindex="0"><thead><tr><th>Query</th><th>best cosine</th></tr></thead><tbody><tr><td>real queries (45 calibration set)</td><td>0.45 – 0.65</td></tr><tr><td><strong>Michael Jackson (no film)</strong></td><td><strong>0.37</strong></td></tr><tr><td><strong>quantum mechanics textbook (no film)</strong></td><td><strong>0.39</strong></td></tr></tbody></table><h2 id="three-confidence-tiers" tabindex="-1">Three confidence tiers <a class="header-anchor" href="#three-confidence-tiers" aria-label="Permalink to &quot;Three confidence tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>cosine</th><th>Banner</th><th>% ceiling</th></tr></thead><tbody><tr><td>high</td><td>≥ 0.52</td><td>✅ strong match</td><td>95%</td></tr><tr><td>mid</td><td>0.45 – 0.52</td><td>◐ partial match</td><td>68%</td></tr><tr><td>low</td><td>&lt; 0.45</td><td>⚠ no strong match · semantic guess</td><td>42% + warning</td></tr></tbody></table><ul><li><strong>The ceiling carries the honest signal</strong>: #1&#39;s % reflects &quot;does the library have this&quot; (95 / 68 / 42), no longer always 95%.</li><li><strong>Position within a tier = CE ordering</strong> (the absolute value is meaningless); min-maxed over the <strong>full candidate pool</strong>, so a given film&#39;s % is stable no matter how many results you show.</li><li>Honest at the edges: cosine catches gross out-of-domain (MJ, quantum physics), but soft out-of-domain (&quot;how to file taxes,&quot; cosine 0.47) overlaps the weakest real queries and can&#39;t be told apart → it lands in <em>mid</em> (caps 68%) rather than faking a strong match.</li></ul><h2 id="where-this-rule-came-from" tabindex="-1">Where this rule came from <a class="header-anchor" href="#where-this-rule-came-from" aria-label="Permalink to &quot;Where this rule came from&quot;">​</a></h2><p>From a real incident: searching &quot;Michael Jackson,&quot; none of the 667 films were relevant, yet #1 was a war-crime drama labeled 100%. The full debugging record — symptom, root cause, measurement calibration, fix → <a href="/film-brain/en/mj-case">Debugging log</a>.</p>',12))])}const v=o(u,[["render",g]]);export{k as __pageData,v as default};
